#!/usr/bin/env python3
"""Generate AXP Historical Stock Performance Report."""

import csv
import math
from datetime import datetime, date
from collections import defaultdict

# ── Load Data ──────────────────────────────────────────────────────────
rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for r in reader:
        dt_str = r['Date'][:10]
        dt = datetime.strptime(dt_str, '%Y-%m-%d').date()
        rows.append({
            'date': dt,
            'open': float(r['Open']),
            'high': float(r['High']),
            'low': float(r['Low']),
            'close': float(r['Close']),
            'volume': int(r['Volume']),
            'dividends': float(r['Dividends']),
            'splits': float(r['Stock Splits']),
        })

rows.sort(key=lambda x: x['date'])
N = len(rows)
first = rows[0]
last = rows[-1]

# ── KPI Calculations ──────────────────────────────────────────────────
# 1. Cumulative Total Return
cum_return = (last['close'] / first['close'] - 1) * 100

# 2. CAGR
years = (last['date'] - first['date']).days / 365.25
cagr = (pow(last['close'] / first['close'], 1 / years) - 1) * 100

# 3. Maximum Drawdown
peak = rows[0]['close']
max_dd = 0
max_dd_peak_date = rows[0]['date']
max_dd_trough_date = rows[0]['date']
dd_peak_date = rows[0]['date']
for r in rows:
    if r['close'] > peak:
        peak = r['close']
        dd_peak_date = r['date']
    dd = (r['close'] - peak) / peak
    if dd < max_dd:
        max_dd = dd
        max_dd_peak_date = dd_peak_date
        max_dd_trough_date = r['date']
max_dd_pct = max_dd * 100

# 4. Annualized Volatility (daily returns stdev * sqrt(252))
daily_returns = []
for i in range(1, N):
    if rows[i-1]['close'] != 0:
        ret = (rows[i]['close'] - rows[i-1]['close']) / rows[i-1]['close']
        daily_returns.append(ret)
mean_ret = sum(daily_returns) / len(daily_returns)
var_ret = sum((r - mean_ret)**2 for r in daily_returns) / (len(daily_returns) - 1)
daily_vol = math.sqrt(var_ret)
annual_vol = daily_vol * math.sqrt(252) * 100

# 5. Total Dividends Paid Per Share
total_divs = sum(r['dividends'] for r in rows)

# ── All-Time High / Low ──────────────────────────────────────────────
ath = max(rows, key=lambda r: r['close'])
atl = min(rows, key=lambda r: r['close'])

# ── Major Drawdown Episodes ──────────────────────────────────────────
def find_drawdowns(data, top_n=5):
    episodes = []
    peak_val = data[0]['close']
    peak_dt = data[0]['date']
    in_dd = False
    current_trough_val = peak_val
    current_trough_dt = peak_dt
    current_peak_val = peak_val
    current_peak_dt = peak_dt

    for i, r in enumerate(data):
        if r['close'] >= peak_val:
            if in_dd:
                dd_pct = (current_trough_val - current_peak_val) / current_peak_val * 100
                recovery_dt = r['date']
                episodes.append({
                    'peak_date': current_peak_dt,
                    'trough_date': current_trough_dt,
                    'recovery_date': recovery_dt,
                    'peak_val': current_peak_val,
                    'trough_val': current_trough_val,
                    'dd_pct': dd_pct,
                })
                in_dd = False
            peak_val = r['close']
            peak_dt = r['date']
        else:
            if not in_dd:
                in_dd = True
                current_peak_val = peak_val
                current_peak_dt = peak_dt
                current_trough_val = r['close']
                current_trough_dt = r['date']
            if r['close'] < current_trough_val:
                current_trough_val = r['close']
                current_trough_dt = r['date']

    if in_dd:
        dd_pct = (current_trough_val - current_peak_val) / current_peak_val * 100
        episodes.append({
            'peak_date': current_peak_dt,
            'trough_date': current_trough_dt,
            'recovery_date': None,
            'peak_val': current_peak_val,
            'trough_val': current_trough_val,
            'dd_pct': dd_pct,
        })

    episodes.sort(key=lambda x: x['dd_pct'])
    return episodes[:top_n]

top_drawdowns = find_drawdowns(rows, 7)

# ── Bull / Bear Phases (simplified: 20% thresholds) ─────────────────
def identify_phases(data):
    phases = []
    phase_start = 0
    phase_start_price = data[0]['close']
    direction = None  # 'bull' or 'bear'
    local_extreme = data[0]['close']
    local_extreme_idx = 0

    for i in range(1, len(data)):
        price = data[i]['close']
        if direction is None:
            if price >= phase_start_price * 1.20:
                direction = 'bull'
                local_extreme = price
                local_extreme_idx = i
            elif price <= phase_start_price * 0.80:
                direction = 'bear'
                local_extreme = price
                local_extreme_idx = i
        elif direction == 'bull':
            if price > local_extreme:
                local_extreme = price
                local_extreme_idx = i
            elif price <= local_extreme * 0.80:
                phases.append({
                    'type': 'bull',
                    'start_date': data[phase_start]['date'],
                    'end_date': data[local_extreme_idx]['date'],
                    'start_price': phase_start_price,
                    'end_price': local_extreme,
                    'return_pct': (local_extreme / phase_start_price - 1) * 100,
                })
                phase_start = local_extreme_idx
                phase_start_price = local_extreme
                direction = 'bear'
                local_extreme = price
                local_extreme_idx = i
        elif direction == 'bear':
            if price < local_extreme:
                local_extreme = price
                local_extreme_idx = i
            elif price >= local_extreme * 1.20:
                phases.append({
                    'type': 'bear',
                    'start_date': data[phase_start]['date'],
                    'end_date': data[local_extreme_idx]['date'],
                    'start_price': phase_start_price,
                    'end_price': local_extreme,
                    'return_pct': (local_extreme / phase_start_price - 1) * 100,
                })
                phase_start = local_extreme_idx
                phase_start_price = local_extreme
                direction = 'bull'
                local_extreme = price
                local_extreme_idx = i

    # Close the last phase
    if direction and len(data) > 0:
        phases.append({
            'type': direction if (direction == 'bull' and data[-1]['close'] >= phase_start_price) or (direction == 'bear' and data[-1]['close'] < phase_start_price) else ('bull' if data[-1]['close'] >= phase_start_price else 'bear'),
            'start_date': data[phase_start]['date'],
            'end_date': data[-1]['date'],
            'start_price': phase_start_price,
            'end_price': data[-1]['close'],
            'return_pct': (data[-1]['close'] / phase_start_price - 1) * 100,
        })

    return phases

phases = identify_phases(rows)

# ── Decade-by-Decade Analysis ────────────────────────────────────────
def decade_label(y):
    d = (y // 10) * 10
    return f"{d}s"

decade_data = defaultdict(list)
for r in rows:
    dec = decade_label(r['date'].year)
    decade_data[dec].append(r)

decade_stats = {}
for dec in sorted(decade_data.keys()):
    d = decade_data[dec]
    start_close = d[0]['close']
    end_close = d[-1]['close']
    total_ret = (end_close / start_close - 1) * 100
    yrs = max((d[-1]['date'] - d[0]['date']).days / 365.25, 0.01)
    dec_cagr = (pow(end_close / start_close, 1 / yrs) - 1) * 100
    rets = []
    for i in range(1, len(d)):
        if d[i-1]['close'] != 0:
            rets.append((d[i]['close'] - d[i-1]['close']) / d[i-1]['close'])
    if len(rets) > 1:
        m = sum(rets) / len(rets)
        v = sum((x - m)**2 for x in rets) / (len(rets) - 1)
        vol = math.sqrt(v) * math.sqrt(252) * 100
    else:
        vol = 0
    pk = d[0]['close']
    mdd = 0
    for r in d:
        if r['close'] > pk:
            pk = r['close']
        dd = (r['close'] - pk) / pk
        if dd < mdd:
            mdd = dd
    div_total = sum(r['dividends'] for r in d)
    hi = max(d, key=lambda x: x['close'])
    lo = min(d, key=lambda x: x['close'])
    decade_stats[dec] = {
        'total_return': total_ret,
        'cagr': dec_cagr,
        'volatility': vol,
        'max_drawdown': mdd * 100,
        'dividends': div_total,
        'high': hi['close'],
        'high_date': hi['date'],
        'low': lo['close'],
        'low_date': lo['date'],
        'start_price': start_close,
        'end_price': end_close,
        'num_days': len(d),
    }

# ── Dividend History ─────────────────────────────────────────────────
div_events = [r for r in rows if r['dividends'] > 0]
div_by_year = defaultdict(float)
for r in div_events:
    div_by_year[r['date'].year] += r['dividends']

# ── Stock Split Events ───────────────────────────────────────────────
split_events = [r for r in rows if r['splits'] != 0]

# ── Sub-period CAGR ──────────────────────────────────────────────────
sub_periods = [
    ('1972-2026 (Full)', rows[0], rows[-1]),
]
# Find rows for sub-period boundaries
def find_closest(data, target_year, month=1, day=1):
    target = date(target_year, month, day)
    best = None
    best_diff = None
    for r in data:
        diff = abs((r['date'] - target).days)
        if best_diff is None or diff < best_diff:
            best = r
            best_diff = diff
    return best

for start_y, end_y in [(1972, 1980), (1980, 1990), (1990, 2000), (2000, 2010), (2010, 2020), (2020, 2026)]:
    s = find_closest(rows, start_y)
    e = find_closest(rows, end_y, 3 if end_y == 2026 else 1)
    yrs = (e['date'] - s['date']).days / 365.25
    if yrs > 0:
        c = (pow(e['close'] / s['close'], 1 / yrs) - 1) * 100
        sub_periods.append((f'{start_y}–{end_y}', s, e))

# ── Rolling Volatility Data (252-day rolling) ────────────────────────
rolling_vol_data = []
window = 252
for i in range(window, N):
    chunk_rets = []
    for j in range(i - window + 1, i + 1):
        if rows[j-1]['close'] != 0:
            chunk_rets.append((rows[j]['close'] - rows[j-1]['close']) / rows[j-1]['close'])
    if len(chunk_rets) > 1:
        m = sum(chunk_rets) / len(chunk_rets)
        v = sum((x - m)**2 for x in chunk_rets) / (len(chunk_rets) - 1)
        rv = math.sqrt(v) * math.sqrt(252) * 100
        rolling_vol_data.append((rows[i]['date'], rv))

# ── Volume Analysis ──────────────────────────────────────────────────
# Monthly average volume
monthly_vol = defaultdict(list)
for r in rows:
    if r['volume'] > 0:
        key = f"{r['date'].year}-{r['date'].month:02d}"
        monthly_vol[key].append(r['volume'])

monthly_avg_vol = {}
for k in sorted(monthly_vol.keys()):
    monthly_avg_vol[k] = sum(monthly_vol[k]) / len(monthly_vol[k])

