# ── Build HTML ────────────────────────────────────────────────────────
def fmt_pct(v):
    return f"{v:+.2f}%" if v < 0 or v >= 0 else f"{v:.2f}%"

def fmt_price(v):
    return f"${v:,.2f}"

def fmt_num(v):
    if v >= 1e9:
        return f"{v/1e9:.1f}B"
    if v >= 1e6:
        return f"{v/1e6:.1f}M"
    if v >= 1e3:
        return f"{v/1e3:.1f}K"
    return f"{v:,.0f}"

def fmt_date(d):
    return d.strftime('%b %d, %Y')

# Build drawdown rows
dd_html = ""
for i, dd in enumerate(top_drawdowns):
    recovery_str = fmt_date(dd['recovery_date']) if dd['recovery_date'] else "Not recovered"
    dd_html += f"""
