    if ratio == 2.0:
        label = "2-for-1"
    elif ratio == 3.0:
        label = "3-for-1"
    elif ratio == 4.0:
        label = "4-for-1"
    else:
        label = f"{ratio}-for-1"
    splits_html += f"""
    <tr>
        <td>{fmt_date(s['date'])}</td>
        <td>{label}</td>
        <td>{fmt_price(s['close'])}</td>
    </tr>"""

# Sub-period CAGR HTML
