for label, s, e in sub_periods:
    yrs = (e['date'] - s['date']).days / 365.25
    c = (pow(e['close'] / s['close'], 1 / yrs) - 1) * 100 if yrs > 0 else 0
    css = "positive" if c > 0 else "negative"
    subperiod_html += f"""
